WITH parsed AS (SELECT id, service, level, status_code, COALESCE(context['region'], 'direct') AS region_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier AS tier, context['region'] AS region, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text FROM app_logs) SELECT *, AVG(status_code) OVER (PARTITION BY level, tier ORDER BY status_code, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) AS status_code_avg_3_prior, LAG(status_code, 2) OVER (PARTITION BY level ORDER BY status_code, id) AS prev_status_code FROM parsed;
